package io.github.diodeme.ji.host;

import com.google.protobuf.ByteString;
import io.github.diodeme.ji.hcp.v1.Command;
import io.github.diodeme.ji.hcp.v1.DurableEvent;
import io.github.diodeme.ji.hcp.v1.Envelope;
import io.github.diodeme.ji.hcp.v1.SnapshotChunk;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.List;

/** Protobuf HCP v1 handshake/snapshot/replay mapper for the local Host. */
public final class HcpSessionGateway {
    public static final int PROTOCOL_VERSION = 1;
    private static final int MAX_ENVELOPE_BYTES = 1024 * 1024;
    private final HostStore store;

    public HcpSessionGateway(HostStore store) {
        this.store = store;
    }

    public List<Envelope> connect(String connectionId, String sessionId, long lastAckSeq, long knownSnapshotRevision) {
        HostStore.Snapshot snapshot = store.snapshot(sessionId);
        var output = new ArrayList<Envelope>();
        if (knownSnapshotRevision != snapshot.revision() || lastAckSeq > snapshot.baseEventSeq()) {
            output.add(snapshotEnvelope(connectionId, snapshot));
            lastAckSeq = snapshot.baseEventSeq();
        }
        for (HostStore.DurableEvent event : store.replay(sessionId, lastAckSeq)) {
            output.add(Envelope.newBuilder().setProtocolVersion(PROTOCOL_VERSION).setConnectionId(connectionId)
                    .setDurableEvent(DurableEvent.newBuilder().setEventSeq(event.eventSeq())
                            .setSnapshotRevision(event.snapshotRevision()).setEventType(event.eventType())
                            .setPayload(ByteString.copyFrom(event.payload()))).build());
        }
        return List.copyOf(output);
    }

    public HostStore.Commit accept(Command command, String payloadHash, String resultRef, String eventType, byte[] eventPayload) {
        if (command.getSerializedSize() > MAX_ENVELOPE_BYTES) throw new IllegalArgumentException("protocol.invalid_message");
        return store.commit(command.getSessionId(), command.getCommandId(), payloadHash, resultRef,
                eventType, eventPayload, command.getExpectedRevision());
    }

    private static Envelope snapshotEnvelope(String connectionId, HostStore.Snapshot snapshot) {
        byte[] digest;
        try { digest = MessageDigest.getInstance("SHA-256").digest(snapshot.payload()); }
        catch (java.security.NoSuchAlgorithmException exception) { throw new IllegalStateException(exception); }
        return Envelope.newBuilder().setProtocolVersion(PROTOCOL_VERSION).setConnectionId(connectionId)
                .setSnapshotChunk(SnapshotChunk.newBuilder().setSnapshotRevision(snapshot.revision())
                        .setChunkIndex(0).setChunkCount(1).setPayload(ByteString.copyFrom(snapshot.payload()))
                        .setTotalSha256(ByteString.copyFrom(digest))).build();
    }
}

